(function(){var DICT={"Home":{zh:"首页",en:"Home"},"首页":{zh:"首页",en:"Home"},"首頁":{zh:"首页",en:"Home"},"English":{zh:"英文",en:"English"},"中文":{zh:"中文",en:"Chinese"},"Novels":{zh:"小说",en:"Novels"},"小说":{zh:"小说",en:"Novels"},"Poems":{zh:"诗歌",en:"Poems"},"诗歌":{zh:"诗歌",en:"Poems"},"Prose":{zh:"散文",en:"Prose"},"散文":{zh:"散文",en:"Prose"},"第七层":{zh:"第七层",en:"7th Floor"},"7th Floor":{zh:"第七层",en:"7th Floor"},"Life":{zh:"生活",en:"Life"},"生活":{zh:"生活",en:"Life"},"Tech":{zh:"科技",en:"Tech"},"科技":{zh:"科技",en:"Tech"},"技术":{zh:"技术",en:"Tech"},"Art":{zh:"艺术",en:"Art"},"艺术":{zh:"艺术",en:"Art"},"Fiction":{zh:"小说",en:"Fiction"},"Poetry":{zh:"诗歌",en:"Poetry"},"Essay":{zh:"散文",en:"Essay"},"Essays":{zh:"散文",en:"Essays"},"随笔":{zh:"随笔",en:"Musings"},"笔记":{zh:"笔记",en:"Notes"},"Notes":{zh:"笔记",en:"Notes"},"日记":{zh:"日记",en:"Diary"},"Diary":{zh:"日记",en:"Diary"},"翻译":{zh:"翻译",en:"Translation"},"Translation":{zh:"翻译",en:"Translation"},"书评":{zh:"书评",en:"Book Reviews"},"读书":{zh:"读书",en:"Reading"},"Reading":{zh:"读书",en:"Reading"},"Reviews":{zh:"评论",en:"Reviews"},"评论":{zh:"评论",en:"Reviews"},"摄影":{zh:"摄影",en:"Photography"},"Photography":{zh:"摄影",en:"Photography"},"旅行":{zh:"旅行",en:"Travel"},"Travel":{zh:"旅行",en:"Travel"},"美食":{zh:"美食",en:"Food"},"Food":{zh:"美食",en:"Food"},"音乐":{zh:"音乐",en:"Music"},"Music":{zh:"音乐",en:"Music"},"电影":{zh:"电影",en:"Films"},"Film":{zh:"电影",en:"Films"},"Movies":{zh:"电影",en:"Movies"},"编程":{zh:"编程",en:"Programming"},"Programming":{zh:"编程",en:"Programming"},"Code":{zh:"代码",en:"Code"},"设计":{zh:"设计",en:"Design"},"Design":{zh:"设计",en:"Design"},"AI":{zh:"AI",en:"AI"},"教程":{zh:"教程",en:"Tutorials"},"Tutorial":{zh:"教程",en:"Tutorial"},"思考":{zh:"思考",en:"Thoughts"},"Thoughts":{zh:"思考",en:"Thoughts"},"随想":{zh:"随想",en:"Reflections"}};window.__rinuanMonths=['January','February','March','April','May','June','July','August','September','October','November','December'];window.__rinuanGetTx=function(tag){return Object.prototype.hasOwnProperty.call(DICT,tag)?DICT[tag]:{zh:tag,en:tag};};window.__rinuanTranslateTags=function(root){root.querySelectorAll('.translatable-tag').forEach(function(link){var raw=link.getAttribute('data-raw-tag');if(!raw)return;var tx=window.__rinuanGetTx(raw);var zh=link.querySelector('.lang-zh');var en=link.querySelector('.lang-en');if(zh)zh.textContent=tx.zh;if(en)en.textContent=tx.en;});};})();
