(function(){if(window.__rinuanTranslateTags)window.__rinuanTranslateTags(document);var nav=document.querySelector('nav.main-nav');if(!nav)return;var navList=nav.querySelector('ul');if(!navList)return;var norm=function(p){try{p=decodeURIComponent(p);}catch(e){}
return p.replace(/\/+$/,'')||'/';};var here=norm(location.pathname);var links=nav.querySelectorAll('a');var active=null;links.forEach(function(a){var p;try{p=norm(new URL(a.href,location.origin).pathname);}catch(e){return;}
if(p===here)active=a;});if(!active&&here==='/'&&links[0])active=links[0];if(active){active.classList.add('is-active');active.setAttribute('aria-current','page');}
var onWheel=function(e){if(Math.abs(e.deltaY)<=Math.abs(e.deltaX))return;var dir=e.deltaY>0?1:-1;var atEnd=(dir>0&&nav.scrollLeft>=nav.scrollWidth-nav.clientWidth-1)||(dir<0&&nav.scrollLeft<=0);if(atEnd)return;e.preventDefault();nav.scrollLeft+=e.deltaY;};var wheelBound=false;var checkQueued=false;var check=function(){checkQueued=false;var scrolling=navList.scrollWidth>nav.clientWidth+1;nav.classList.toggle('is-scrolling',scrolling);if(scrolling!==wheelBound){wheelBound=scrolling;if(scrolling)nav.addEventListener('wheel',onWheel,{passive:false});else nav.removeEventListener('wheel',onWheel);}};var scheduleCheck=function(){if(checkQueued)return;checkQueued=true;requestAnimationFrame(check);};check();if('ResizeObserver'in window){var navResizeObserver=new ResizeObserver(scheduleCheck);navResizeObserver.observe(nav);navResizeObserver.observe(navList);}else{window.addEventListener('resize',scheduleCheck);}
if(document.fonts&&document.fonts.ready)document.fonts.ready.then(scheduleCheck);})();
