(function(){var self=document.currentScript;if(!self)return;var path=location.pathname;try{path=decodeURIComponent(path);}catch(e){}
var label=path.match(/\/search\/label\/(.+?)\/?$/);var archive=path.match(/^\/(\d{4})(?:\/(\d{2}))?\/?$/);var q=null;if(/^\/search\/?$/.test(path)){try{q=new URLSearchParams(location.search).get('q');}catch(e){}}
var kicker,titleZh,titleEn,rawTag=null;if(label){kicker={zh:'分类',en:'Category'};rawTag=label[1];var tx=window.__rinuanGetTx?window.__rinuanGetTx(rawTag):{zh:rawTag,en:rawTag};titleZh=tx.zh;titleEn=tx.en;}else if(q){kicker={zh:'搜索',en:'Search'};titleZh=titleEn='“'+q+'”';}else if(archive){kicker={zh:'归档',en:'Archive'};var y=+archive[1];if(archive[2]){var mo=+archive[2];titleZh=y+'年'+mo+'月';titleEn=(window.__rinuanMonths?window.__rinuanMonths[mo-1]+' ':'')+y;}else{titleZh=y+'年';titleEn=String(y);}}else{return;}
var bi=function(tag,cls,zh,en){var el=document.createElement(tag);el.className=cls;var s1=document.createElement('span');s1.className='lang-zh';s1.textContent=zh;var s2=document.createElement('span');s2.className='lang-en';s2.textContent=en;el.append(s1,s2);return el;};var hdr=document.createElement('header');hdr.className='listing-header';hdr.append(bi('p','listing-kicker',kicker.zh,kicker.en));var title=bi('h2','listing-title'+(rawTag?' translatable-tag':''),titleZh,titleEn);if(rawTag)title.setAttribute('data-raw-tag',rawTag);hdr.append(title);self.insertAdjacentElement('afterend',hdr);})();
