(()=>{const list=document.getElementById('related-posts-list');const wrapper=document.querySelector('.related-posts');if(!list)return;const label=list.getAttribute('data-label');if(!label)return;const currentUrl=window.location.href.split(/[?#]/)[0];let relatedPostsScript=null;let relatedPostsTimeout=null;let relatedPostsSettled=false;const cleanupRelatedPosts=()=>{if(relatedPostsTimeout){clearTimeout(relatedPostsTimeout);relatedPostsTimeout=null;}
if(relatedPostsScript&&relatedPostsScript.parentNode)relatedPostsScript.remove();relatedPostsScript=null;window.loadRelatedPosts=()=>{};};window.loadRelatedPosts=json=>{if(relatedPostsSettled)return;relatedPostsSettled=true;list.textContent='';let count=0;if(json&&json.feed&&json.feed.entry){const posts=json.feed.entry;for(let i=0;i<posts.length;i++){const title=posts[i].title&&posts[i].title.$t?posts[i].title.$t:'';if(!title)continue;let url='';const links=posts[i].link||[];for(let j=0;j<links.length;j++){if(links[j].rel==='alternate'){url=links[j].href;break;}}
if(!url||url.split(/[?#]/)[0]===currentUrl)continue;const item=document.createElement('li');const link=document.createElement('a');link.href=url;link.textContent=title;item.appendChild(link);list.appendChild(item);count++;if(count>=3)break;}}
if(count){if(wrapper)wrapper.classList.add('is-loaded');if(window.__rinuanToVariant){window.__rinuanToVariant(list);}}
cleanupRelatedPosts();};let requested=false;const requestRelatedPosts=()=>{if(requested)return;requested=true;const script=document.createElement('script');script.async=true;script.src='/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json-in-script&callback=loadRelatedPosts&max-results=6';relatedPostsScript=script;script.onerror=()=>{relatedPostsSettled=true;cleanupRelatedPosts();};relatedPostsTimeout=setTimeout(()=>{relatedPostsSettled=true;cleanupRelatedPosts();},8000);document.body.appendChild(script);};if('requestIdleCallback'in window){requestIdleCallback(requestRelatedPosts,{timeout:3500});}else{const later=()=>setTimeout(requestRelatedPosts,1600);if(document.readyState==='complete')later();else window.addEventListener('load',later,{once:true});}})();
