(function(){let PUNCT=null;try{PUNCT=new RegExp('(?<=[，。；！？：、:])');}catch(e){}
const wrap=function(el){if(!el||!PUNCT)return;const parts=el.textContent.split(PUNCT).filter(Boolean);if(parts.length<=1)return;el.innerHTML='';parts.forEach(function(part){const chunk=document.createElement('span');chunk.className='title-chunk';chunk.textContent=part;el.appendChild(chunk);});};window.__rinuanWrapTitles=function(root){root.querySelectorAll('h2.post-title').forEach(function(h2){wrap(h2.querySelector('a')||h2);});};wrap(document.querySelector('.header-logo-link > span:last-child'));window.__rinuanWrapTitles(document);})();(function(){if(document.documentElement.classList.contains('steam-done'))return;var go=function(){requestAnimationFrame(function(){document.documentElement.classList.add('steam-go');try{sessionStorage.setItem('steamDrawn','1');}catch(e){}});};if(document.readyState==='complete')go();else window.addEventListener('load',go,{once:true});})();(function(){if(window.innerWidth<1024)return;const postBody=document.querySelector('.post-body.full-content');if(!postBody)return;const parseDate=function(){const meta=document.querySelector('.post-meta');if(meta){for(let i=0;i<meta.childNodes.length;i++){const n=meta.childNodes[i];if(n.nodeType===3&&n.textContent.trim()){const d=new Date(n.textContent.trim());if(!isNaN(d.getTime()))return d;break;}}}
const sibling=document.querySelector('.date-header');if(sibling){const ds=new Date(sibling.textContent.trim());if(!isNaN(ds.getTime()))return ds;}
const m=window.location.pathname.match(/\/(\d{4})\/(\d{2})\//);if(m)return new Date(parseInt(m[1],10),parseInt(m[2],10)-1,1);return null;};const estimateReadMinutes=function(text){if(!text)return 1;const cjk=(text.match(/[\u4e00-\u9fff]/g)||[]).length;const noCjk=text.replace(/[\u4e00-\u9fff]/g,' ');const enWords=(noCjk.match(/[A-Za-z0-9]+/g)||[]).length;const minutes=cjk/350+enWords/220;return Math.max(1,Math.round(minutes));};const EN_MONTHS=(window.__rinuanMonths||[]).map(m=>m.toUpperCase());const ZH_MONTHS=['一月','二月','三月','四月','五月','六月','七月','八月','九月','十月','十一月','十二月'];const ZH_DIGITS=['〇','一','二','三','四','五','六','七','八','九'];const toZhYear=function(year){return String(year).split('').map(function(d){return ZH_DIGITS[parseInt(d,10)];}).join('');};const toZhMinutes=function(n){if(n<10)return ZH_DIGITS[n];if(n>=100)return String(n);const tens=Math.floor(n/10);const ones=n%10;const tensStr=tens===1?'十':ZH_DIGITS[tens]+'十';return ones===0?tensStr:tensStr+ZH_DIGITS[ones];};const rails=[];const d=parseDate();if(d){const dateRail=document.createElement('div');dateRail.className='desktop-date-rail';dateRail.setAttribute('aria-hidden','true');dateRail.innerHTML='<span class="lang-zh">'+toZhYear(d.getFullYear())+'·'+ZH_MONTHS[d.getMonth()]+'</span>'+'<span class="lang-en">'+EN_MONTHS[d.getMonth()]+' · '+d.getFullYear()+'</span>';document.body.appendChild(dateRail);rails.push(dateRail);}
const minutes=estimateReadMinutes(postBody.textContent||'');const rtRail=document.createElement('div');rtRail.className='desktop-readtime-rail';rtRail.setAttribute('aria-hidden','true');rtRail.innerHTML='<span class="lang-zh">约 '+toZhMinutes(minutes)+' 分钟</span>'+'<span class="lang-en">'+minutes+' MIN READ</span>';document.body.appendChild(rtRail);rails.push(rtRail);requestAnimationFrame(function(){rails.forEach(function(el){el.classList.add('is-ready');});});})();(function(){const articleBody=document.querySelector('.post-body.full-content');if(!articleBody)return;const bar=document.createElement('div');bar.className='reading-bar';bar.setAttribute('role','button');bar.setAttribute('tabindex','-1');bar.setAttribute('aria-label','返回顶部 / Back to top');const fill=document.createElement('div');fill.className='bar-fill';bar.appendChild(fill);document.body.appendChild(bar);const hint=document.createElement('div');hint.className='reading-hint';hint.setAttribute('aria-hidden','true');hint.innerHTML='<span class="hint-arrow" aria-hidden="true">↑</span>'+'<span class="lang-zh">点击返回顶部</span>'+'<span class="lang-en">Tap to return to the top</span>';document.body.appendChild(hint);const reduceMotion=function(){return window.matchMedia('(prefers-reduced-motion: reduce)').matches;};const toTop=function(){window.scrollTo({top:0,behavior:reduceMotion()?'auto':'smooth'});};bar.addEventListener('click',toTop);bar.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();toTop();}});let hideTimer=null;const showHint=function(duration){hint.classList.add('is-shown');if(hideTimer){clearTimeout(hideTimer);hideTimer=null;}
if(duration)hideTimer=setTimeout(function(){hint.classList.remove('is-shown');},duration);};const hideHint=function(){if(hideTimer){clearTimeout(hideTimer);hideTimer=null;}
hint.classList.remove('is-shown');};bar.addEventListener('mouseenter',function(){showHint(0);});bar.addEventListener('mouseleave',function(){hideHint();});let appeared=false;let completedHinted=false;let barActive=false;let ticking=false;let articleDocBottom=0;let measureArticleRAF=0;let refreshProgressAfterMeasure=function(){};const measureArticle=function(){measureArticleRAF=0;articleDocBottom=articleBody.getBoundingClientRect().bottom+
(window.scrollY||document.documentElement.scrollTop);refreshProgressAfterMeasure();};const scheduleMeasureArticle=function(){if(!measureArticleRAF)measureArticleRAF=requestAnimationFrame(measureArticle);};measureArticle();if('ResizeObserver'in window)new ResizeObserver(scheduleMeasureArticle).observe(articleBody);window.addEventListener('load',scheduleMeasureArticle);const update=function(){ticking=false;const scrollTop=window.scrollY||document.documentElement.scrollTop;const target=Math.max(1,articleDocBottom-window.innerHeight);const pct=Math.min(1,Math.max(0,scrollTop/target));fill.style.transform='scaleX('+pct.toFixed(4)+')';const active=scrollTop>window.innerHeight*0.6;if(active!==barActive){barActive=active;bar.classList.toggle('is-active',active);bar.tabIndex=active?0:-1;}
if(active&&!appeared){appeared=true;showHint(2000);}
if(pct>0.985&&!completedHinted){completedHinted=true;showHint(2000);}
if(!active)hideHint();};const onScroll=function(){if(!ticking){requestAnimationFrame(update);ticking=true;}};refreshProgressAfterMeasure=onScroll;window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',function(){scheduleMeasureArticle();onScroll();},{passive:true});update();})();(function(){if(document.getElementById('error-404'))return;var startMascot=function(bootFromInteraction){var ART={happy:'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/happy.webp',angry:'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/angry.webp',sad:'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/sad.webp',surprised:'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/surprised.webp',shy:'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/shy.webp',confused:'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/confused.webp',excited:'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/excited.webp',sleepy:'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/sleepy.webp','peek-left':'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/peek-left.webp','peek-right':'https://cdn.jsdelivr.net/gh/rinuuan/blog-assets@main/mascot/chibi/peek-right.webp'};var HIDE_KEY='mascotHidden';var CHAT_KEY='mascotChat';var chatLevel='full';try{chatLevel=localStorage.getItem(CHAT_KEY)||'full';}catch(e){}
if(chatLevel!=='full'&&chatLevel!=='less'&&chatLevel!=='mute')chatLevel='full';var ambient=function(){return chatLevel==='full';};var SIZE_KEY='mascotScale';var mascotScale=1;try{var sv=parseFloat(localStorage.getItem(SIZE_KEY));if(sv)mascotScale=Math.min(1.6,Math.max(0.6,sv));}catch(e){}
var wrap=document.createElement('div');wrap.className='mascot';var L=function(zh,en){return'<span class="lang-zh">'+zh+'</span><span class="lang-en">'+en+'</span>';};wrap.innerHTML='<div class="mascot-bubble" aria-hidden="true"><span class="mascot-text"></span></div>'+'<img class="mascot-img" alt="" draggable="false" decoding="async" width="400" height="600"/>';document.body.appendChild(wrap);var topActions=document.querySelector('.top-actions');var gear=document.createElement('button');gear.className='action-btn';gear.id='mascot-settings';gear.type='button';gear.setAttribute('aria-haspopup','true');gear.setAttribute('aria-controls','mascot-menu');gear.setAttribute('aria-expanded','false');gear.setAttribute('aria-label','看板娘设置 / Mascot settings');gear.setAttribute('title','看板娘设置 / Mascot settings');gear.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '+'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+'<circle cx="12" cy="12" r="6"/>'+'<circle cx="12" cy="12" r="2.4"/>'+'<path d="M12 3.5V6M12 20.5V18M3.5 12H6M20.5 12H18M6 6l1.8 1.8M18 6l-1.8 1.8M6 18l1.8-1.8M18 18l-1.8-1.8"/>'+'</svg>';try{if(localStorage.getItem(HIDE_KEY)==='1')gear.classList.add('is-collapsed');}catch(e){}
if(topActions)topActions.insertBefore(gear,topActions.firstChild);else document.body.appendChild(gear);var menu=document.createElement('div');menu.className='mascot-menu';menu.id='mascot-menu';menu.setAttribute('role','group');menu.setAttribute('aria-hidden','true');menu.setAttribute('inert','');menu.setAttribute('aria-label','看板娘设置 / Mascot settings');menu.innerHTML='<div class="menu-title">'+L('台词','Chatter')+'</div>'+'<button type="button" data-level="full">'+L('活泼','Lively')+'</button>'+'<button type="button" data-level="less">'+L('少话','Quiet')+'</button>'+'<button type="button" data-level="mute">'+L('静音','Mute')+'</button>'+'<hr/>'+'<div class="menu-title">'+L('大小','Size')+'</div>'+'<input type="range" class="mascot-size" min="0.6" max="1.6" step="0.02" aria-label="看板娘大小 / Mascot size"/>'+'<hr/>'+'<button type="button" class="menu-hide" data-act="hide">'+L('收起看板娘','Hide mascot')+'</button>';document.body.appendChild(menu);var reopen=document.createElement('button');reopen.className='mascot-reopen';reopen.type='button';reopen.setAttribute('aria-label','显示看板娘 / Show mascot');reopen.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '+'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+'<path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>'+'<path d="M8 10h.01M12 10h.01M16 10h.01"/>'+'</svg>';document.body.appendChild(reopen);var imgEl=wrap.querySelector('.mascot-img');var bubble=wrap.querySelector('.mascot-bubble');var textEl=wrap.querySelector('.mascot-text');var imgRetried=false;imgEl.addEventListener('load',function(){imgRetried=false;});imgEl.onerror=function(){var src=imgEl.getAttribute('src');if(!imgRetried&&src){imgRetried=true;imgEl.removeAttribute('src');setTimeout(function(){if(!imgEl.getAttribute('src'))imgEl.src=src;},800);return;}
wrap.classList.add('is-hidden');wrap.remove();gear.remove();menu.remove();reopen.remove();};var ensureLoaded=function(){if(!imgEl.getAttribute('src'))imgEl.src=ART.happy;};var lang=function(){return document.documentElement.getAttribute('data-lang')==='en'?'en':'zh';};var s2tConverter=null;var toVariant=function(text){if(document.documentElement.getAttribute('data-variant')==='trad'&&window.OpenCC){try{if(!s2tConverter)s2tConverter=window.OpenCC.Converter({from:'cn',to:'tw'});return s2tConverter(text);}catch(e){}}
return text;};var loaded={happy:true};var artToken=0;var setArt=function(name,isPeek){var url=ART[name]||ART.happy;var token=++artToken;if(loaded[name]){imgEl.src=url;return;}
var pre=new Image();pre.onload=function(){loaded[name]=true;if(token===artToken)imgEl.src=url;};if(isPeek){pre.onerror=function(){if(token===artToken)setArt(currentMood,false);};}
pre.src=url;};var currentMood='happy';var setMood=function(mood){currentMood=mood;setArt(mood,false);};var peekWarmed={};var warmPeek=function(side){var name='peek-'+side;if(peekWarmed[name])return;peekWarmed[name]=true;var pre=new Image();pre.onload=function(){loaded[name]=true;};pre.src=ART[name]||ART.happy;};var idleTimer=null;function resetIdle(){if(idleTimer){clearTimeout(idleTimer);idleTimer=null;}
if(wrap.classList.contains('is-hidden')||!ambient())return;idleTimer=setTimeout(function(){if(ambient()&&!wrap.classList.contains('is-hidden'))sayMoods(IDLE_MOODS);},60000+Math.random()*60000);}
var bubbleTimer=null;var say=function(line,hold,force){if(!line)return;if(wrap.classList.contains('is-hidden'))return;if(chatLevel==='mute'&&!force)return;if(tucked)untuck();setMood(line.mood);var txt=line[lang()]||line.zh;textEl.textContent=lang()==='zh'?toVariant(txt):txt;if(updateBubbleSide)updateBubbleSide();bubble.classList.add('is-shown');if(bubbleTimer)clearTimeout(bubbleTimer);bubbleTimer=setTimeout(function(){bubble.classList.remove('is-shown');},hold||4800);resetIdle();if(scheduleTuck)scheduleTuck();};var lastLine=null;var pick=function(a){if(a.length<2)return a[0];var l;do{l=a[Math.floor(Math.random()*a.length)];}while(l===lastLine);lastLine=l;return l;};var pickLineAvoidMood=function(lines,avoidMood){var pool=lines.filter(function(line){return line.mood!==avoidMood;});return pick(pool.length?pool:lines);};var pickMood=function(moodArr,avoidMood){var pool=moodArr.filter(function(m){return m!==avoidMood;});if(!pool.length)pool=moodArr;return pool[Math.floor(Math.random()*pool.length)];};var sayMoods=function(moodArr){var m=pickMood(moodArr);var l=pick(MOODS[m]);say({mood:m,zh:l.zh,en:l.en});};var reactToClick=function(){var m=pickMood(CLICK_MOODS,currentMood);var l=pick(MOODS[m]);if(chatLevel==='mute'){setMood(m);resetIdle();return;}
say({mood:m,zh:l.zh,en:l.en});};var CLICK_MOODS=['surprised','angry','shy','excited','happy','confused'];var IDLE_MOODS=['sleepy','sad','confused','shy'];var MOODS={happy:[{zh:'今天份的我，准时上线陪你啦~',en:'Today’s dose of me, clocking in to keep you company~'},{zh:'看到你我就开心~',en:'Seeing you just makes me happy~'},{zh:'嘿嘿，心情好好哦！',en:'Heehee, I’m in such a good mood!'},{zh:'和你待一起真愉快~',en:'It’s so nice hanging out with you~'},{zh:'今天的你…被我偷偷打了满分。',en:'Today’s you… got full marks from me, secretly.'},{zh:'啦啦啦~ 哼着小曲儿。',en:'La-la-la~ just humming along.'},{zh:'阳光正好，适合发呆。',en:'Lovely sun — perfect for daydreaming.'},{zh:'要不要一起偷个懒？',en:'Shall we be a little lazy together?'},{zh:'谢谢你又来啦！',en:'Thanks for dropping by again!'},{zh:'摸摸头，今天辛苦啦~',en:'There there — you’ve worked hard today~'},{zh:'心情像棉花糖一样软软的。',en:'I feel as fluffy as cotton candy.'},{zh:'给你一颗甜甜的好心情！',en:'Here’s a sweet little mood, just for you!'},{zh:'我们是好搭档，对吧？',en:'We make a good team, right?'},{zh:'嗯哼，今天也赖着你不走咯~',en:'Mm-hm, I’m sticking to you again today~'},{zh:'笑一个嘛，你笑起来好看。',en:'Give us a smile — you look great smiling.'},{zh:'有你在，这一页都亮了。',en:'With you here, the whole page lights up.'}],excited:[{zh:'哇哇哇！好期待呀！',en:'Wow wow wow! I’m so excited!'},{zh:'冲鸭——！今天超有干劲！',en:'Let’s gooo! So much energy today!'},{zh:'快看快看，我发现新东西啦！',en:'Look look, I found something new!'},{zh:'心跳加速，好兴奋！',en:'My heart’s racing — how thrilling!'},{zh:'一起去探险吧，出发！',en:'Let’s go on an adventure — onward!'},{zh:'噔噔噔！惊喜时间到！',en:'Ta-da! It’s surprise o’clock!'},{zh:'我要蹦起来啦，接住我！',en:'I’m gonna bounce — catch me!'},{zh:'太棒啦，鼓掌鼓掌！',en:'Amazing — clap clap clap!'},{zh:'这个超有意思的，你看！',en:'This is super fun, check it out!'},{zh:'元气全开，无敌啦！',en:'Energy maxed — unstoppable!'},{zh:'等不及想知道接下来呢！',en:'Can’t wait to see what’s next!'},{zh:'哦哦哦！我有个好主意！',en:'Ooh ooh! I’ve got a great idea!'},{zh:'跟上跟上，别掉队哦~',en:'Keep up, keep up — don’t fall behind~'},{zh:'满血复活，继续出发！',en:'Full HP — let’s keep going!'},{zh:'好戏开场啦，搬小板凳！',en:'The show’s starting — grab a seat!'},{zh:'闪闪发光的一