E=[{mood:'happy',zh:'回到老位置~ 这里最舒服啦！',en:'Back to my usual spot~ comfiest here!'},{mood:'excited',zh:'嗖——回家咯！',en:'Whoosh — back home!'}];var HALF=[{mood:'happy',zh:'读到一半啦，我可一直盯着没走神~',en:'Halfway! I’ve been watching the whole time, no spacing out~'},{mood:'excited',zh:'精彩的地方快来了吧？我也好奇！',en:'The good part’s coming, right? I’m curious too!'},{mood:'shy',zh:'陪你读到这里…有点小满足。',en:'Reading this far with you… quietly satisfying.'},{mood:'confused',zh:'唔，前面讲到哪儿了来着？',en:'Um, what was it about so far again?'}];var LONGSTAY=[{mood:'shy',zh:'已经陪你这么久啦…有点开心呢。',en:'We’ve been together a while now… quietly happy.'},{mood:'happy',zh:'时间过得真快，看得入迷了吧？',en:'Time flies — really absorbed, aren’t you?'},{mood:'sleepy',zh:'陪你这么久，我都快长屏幕上啦~',en:'I’ve been with you so long I’m basically part of the screen~'},{mood:'excited',zh:'你是我今天最久的伙伴啦！',en:'You’re my longest-staying friend today!'}];var BACKTOP=[{mood:'happy',zh:'又回到开头啦，再读一遍？',en:'Back at the top — another read?'},{mood:'excited',zh:'嗖地飞回来了，好快！',en:'Whoosh, flew right back — so fast!'},{mood:'surprised',zh:'诶，一下子回顶了？',en:'Huh, back to the top in a blink?'}];var RETURN=[{mood:'excited',zh:'你回来啦！想我没~',en:'You’re back! Did you miss me~'},{mood:'happy',zh:'欢迎回来~ 位子给你留着呢。',en:'Welcome back~ I saved your seat.'},{mood:'surprised',zh:'诶，刚刚去哪儿啦？',en:'Huh, where’d you slip off to?'},{mood:'shy',zh:'刚刚…有点想你了呢。',en:'Just now… I missed you a little.'}];var LABEL_LINES={'中文':[{mood:'happy',zh:'中文专区~ 慢慢读，别噎着。',en:'The Chinese corner~ read slowly, don’t choke.'},{mood:'excited',zh:'方块字真好看，对吧！',en:'Aren’t these square characters lovely!'},{mood:'shy',zh:'我的中文…还在偷偷练呢。',en:'My Chinese… still secretly practising.'}],'English':[{mood:'excited',zh:'English time！我的口语也在偷偷练哦~',en:'English time! I’ve been practising too~'},{mood:'happy',zh:'换个语言换个心情，走起！',en:'New language, new mood — let’s go!'},{mood:'confused',zh:'唔…这个词怎么念来着？',en:'Um… how do you pronounce this one again?'}]};var LABEL_DEFAULT=[{mood:'excited',zh:'这个话题我也想多看看，一起呀！',en:'I want to dig into this one too 